'use strict';
var $=function(id){return document.getElementById(id)}, esc=function(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})};
var demoStyle=document.createElement('style');demoStyle.textContent=".exercise-demo{margin:10px 0 14px;padding:10px;border:1px solid #34463a;border-radius:10px;background:#0b110d}.demo-heading{font-weight:700;margin-bottom:8px;color:#c6f36b}.exercise-demo video{display:block;width:100%;max-height:320px;object-fit:contain;background:#050805;border-radius:8px}.exercise-demo .small{margin:7px 0 0}.demo-video-frame{position:relative;width:100%;aspect-ratio:16/9}.demo-video-frame iframe{position:absolute;inset:0;width:100%;height:100%;border:0;border-radius:8px}.demo-video-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.demo-video-grid video{width:100%;height:auto;aspect-ratio:4/3;object-fit:contain}@media(max-width:520px){.demo-video-grid{grid-template-columns:1fr}}\n";demoStyle.textContent+='.warm-bullets,.exercise-warmups ul{margin:8px 0 0;padding-left:22px}.warm-bullets>li,.exercise-warmups li{padding:3px 0;color:#d8e2d8;font-size:13px;line-height:1.45}.warmcheck{display:flex;align-items:flex-start;gap:7px;font-size:13px;line-height:1.45;color:#d8e2d8}.warmcheck input{flex:0 0 auto;margin:3px 0 0}.exercise-warmups{margin:12px 0;padding:10px 12px;border:1px solid #34463a;border-radius:12px;background:#101813}.exercise-warmups>b{display:block;margin:0;color:#c6f36b;font-size:12px;letter-spacing:.04em;text-transform:uppercase}.exercise-warmups ul{margin-top:5px}';document.head.appendChild(demoStyle);
var originalDraw=draw;
state.settings=state.settings||{calorieTarget:2300,proteinTarget:130};
/* Use the Smith variation for the higher-rep hypertrophy chest day. */
days.C.items[0][0]='Smith-machine bench press';
days.A.items[1][0]='Chest-supported machine row';
days.C.items[3][0]='Incline DB curl (hammer up, supinated down)';
days.T.items.push(['Farmer carry',2,30,45,'seconds']);
var warm={
 A:['3–4 min easy treadmill walk or bike','Arm circles × 8 each way','Scapular push-ups × 8','Unloaded shoulder-blade retractions × 6–8','Bench: empty bar × 8–10, then ~50% working weight × 4–5; optional ~70% × 2 only if needed'],
 B:['3–4 min easy treadmill walk or bike','Scapular pull-ups or active-hang depressions × 6–8','Thoracic rotations × 6 each side','First vertical pull: 1–2 easy ramp-up sets'],
 L:['4–5 min easy bike or treadmill walk','Leg swings × 8 each direction per leg','Ankle rocks × 8 each side','Bodyweight squats × 8; unloaded hip hinges × 6','2–3 submaximal jumps with full reset','First loaded leg lift: 2 easy ramp-up sets'],
 C:['3–4 min easy treadmill walk or bike','Arm circles × 8 each way','Wall slides × 8','Scapular push-ups × 6–8','Bench: empty bar × 8–10, then ~50% working weight × 4–5; optional ~70% × 2 only if needed'],
 T:['2–3 min easy walk or bike','Shoulder circles × 8 each way','Shoulder-blade squeezes × 8','Wrist open/close × 10','One light rehearsal set for the first movement']
};

var formGuides={
 'Bench press':{type:'press',setup:'Eyes under the bar; feet planted; shoulder blades gently retracted and set against the bench. Use a grip that keeps wrists stacked over forearms.',steps:'Unrack with control. Lower toward the lower-to-mid chest while elbows track roughly 30–60° from the torso. Touch softly, then press up and slightly back over the shoulders.',cues:['Keep glutes on the bench and feet firmly planted.','Keep wrists stacked; do not let them fold backward.','Use a repeatable pain-free depth; do not bounce off the chest.'],avoid:'Flaring elbows straight out, bouncing, lifting hips, or forcing painful shoulder depth.',rom:'Use the deepest controlled touch that your shoulder comfort and setup allow.'},
 'Bench press (volume)':{type:'press',setup:'Same setup as strength bench. A slightly closer grip or Smith machine is fine if it improves control and comfort.',steps:'Lower smoothly for about 2 seconds, pause briefly without relaxing, then press while maintaining upper-back position.',cues:['Prioritize controlled reps and a consistent touch point.','Stop 1–2 reps before form breaks down.','Do not chase extra depth by losing shoulder position.'],avoid:'Turning volume sets into grinders or bouncing.',rom:'Controlled full range; no forced stretch.'},
 'Smith-machine bench press':{type:'press',setup:'Set bench so the bar touches lower-to-mid chest. Align the Smith bar path with a comfortable wrist/elbow position; set safeties just below your normal bottom position.',steps:'Unhook with wrists stacked. Lower under control to a comfortable chest touch, then press smoothly along the fixed track.',cues:['Keep shoulder blades stable against the bench.','Keep elbows slightly tucked rather than flared.','Use safeties and test the rack/unrack path before loading.'],avoid:'Setting the bench too far forward/back, bouncing, or using a forced painful bottom position.',rom:'Use a deep, comfortable touch while shoulders stay stable.'},
 'Chest-supported row':{type:'row',setup:'Adjust chest pad so you can reach forward without shoulders being forced painfully forward. Feet braced; neutral wrist.',steps:'Reach with shoulder blades, then drive elbows back. Pause briefly with shoulder blades moving naturally; lower slowly to a controlled stretch.',cues:['Keep chest on pad; avoid shrugging toward ears.','Lead with elbows, not wrists.','Let shoulder blades protract at the bottom without rounding your low back.'],avoid:'Jerking torso off pad or shortening every rep.',rom:'Allow a controlled reach at the bottom and a strong squeeze without cranking elbows far behind torso.'},
 'Chest-supported machine row':{type:'row',setup:'Use the upright chest-supported row machine shown in the reference photo. Sit facing the machine with sternum against the vertical chest pad, feet planted on the footrests and hands on the low handles. Adjust the seat so you can reach without losing chest-pad contact.',steps:'Begin with arms reaching forward and shoulder blades allowed to protract. Pull both handles toward your lower-to-mid ribs by driving elbows back, keeping your chest against the pad. Pause briefly, then let the arms reach forward slowly for a controlled stretch.',cues:['Keep your chest against the vertical pad throughout.','Sit facing the weight-stack/tower; do not face away from the machine.','Lead with elbows and keep wrists neutral.','Allow shoulder blades to move naturally at the stretched start.'],avoid:'Lifting your chest off the pad, rocking your torso, shrugging, or forcing elbows far behind your body.',rom:'Reach forward until the upper back/lats stretch while chest contact remains; finish when elbows reach the torso.'},
 'Incline dumbbell press':{type:'press',setup:'Set bench around 15–30° to bias upper chest without excessive shoulder stress. Feet planted; dumbbells start over upper chest.',steps:'Lower dumbbells slightly outside upper chest with forearms near vertical. Press up and slightly inward without clanking weights.',cues:['Keep shoulder blades stable and ribs controlled.','Use a comfortable deep stretch; stop before front-shoulder discomfort.','Keep wrists stacked over elbows.'],avoid:'Very steep bench angle, bouncing from bottom, or forcing dumbbells together.',rom:'Deepest pain-free position with upper arm controlled; do not chase extreme stretch.'},
 'Cable lateral raise':{type:'raise',attachment:'Single D-handle on the lowest pulley setting; use one handle per arm and train one side at a time.',setup:'Set pulley low. Stand side-on, hold the D-handle with a soft elbow bend; use the free hand for support if helpful.',steps:'Raise arm out and slightly forward in the scapular plane to around shoulder height. Lower slowly until the delt is lengthened without resting the stack.',cues:['Lead with elbow; keep wrist neutral.','Keep torso quiet and shoulder away from ear.','Use a load that allows smooth control.'],avoid:'Swinging, shrugging hard, or turning it into a trap-dominant movement.',rom:'Use the largest comfortable arc without pinching.'},
 'EZ-bar preacher curl':{type:'curl',setup:'Set the preacher bench so the pad supports the backs of your upper arms up toward the armpits. Take the angled EZ-bar grips at a comfortable shoulder-width position; wrists stay aligned with the forearms.',steps:'Begin near full elbow extension without snapping into lockout. Curl the EZ bar toward your shoulders while keeping upper arms planted on the pad. Squeeze briefly, then lower for 2–3 seconds through the same arc.',cues:['Keep both upper arms in contact with the pad.','Use the EZ bar angled grips; let wrists sit naturally.','Do not lift elbows or roll shoulders forward to finish.','Control the stretched bottom; do not bounce.'],avoid:'Using momentum, lifting the elbows off the pad, overextending the elbows, or dropping the eccentric.',rom:'Lower to a deep, comfortable elbow extension while keeping tension and avoiding a hard lockout.'},
 'Incline DB curl (hammer up, supinated down)':{type:'curl',setup:'Set an incline bench around 45–60°. Sit back with head and upper back supported, feet planted, and one dumbbell in each hand. Start with palms facing each other in a neutral hammer grip.',steps:'Keep upper arms hanging slightly behind your torso and elbows quiet. Curl upward with palms facing each other. At the top, rotate both forearms into a palms-up supinated position; lower slowly with palms up. At the bottom, rotate back to neutral before the next rep.',cues:['Hammer/neutral grip on the way up.','Rotate to palms-up only at the top, then use a supinated eccentric.','Keep elbows mostly fixed and shoulders relaxed.','Use lighter loads than a standard incline curl; the rotation should be smooth.'],avoid:'Swinging, letting elbows drift forward, rotating under load abruptly, or losing control at the stretched bottom.',rom:'Use a controlled full elbow range; stop short of any uncomfortable biceps tendon or shoulder stretch.'},
 'Pull-up / assisted pull-up':{type:'pull',setup:"Use a pronated (overhand), closed grip with hands just outside shoulder width—about 1.1–1.3× shoulder width, not an extreme wide grip. Wrap thumbs around the bar. Start in a controlled full hang with elbows straight and shoulders naturally elevated; ribs stacked and legs quiet.",steps:"From the hang, allow the shoulder blades to upwardly rotate. Initiate the pull by drawing them down as elbows bend. Drive elbows down and slightly toward your sides; keep the bar path close. Rise until the chin clearly passes the bar without craning the neck. Lower smoothly until elbows are straight and you regain the controlled hang.",cues:["Hands just outside shoulder width; wrists straight and grip symmetrical.","Think elbows down toward your front pockets, not flared straight sideways.","Keep ribs down, glutes lightly engaged and legs still; a slight hollow-body position is fine.","Let scapulae move naturally: upward rotation at the bottom, then downward rotation/depression as you pull.","Use identical mechanics on a regular bar, assisted machine, bodyweight or weighted pull-up; assistance only changes resistance."],avoid:"Very wide grip, behind-neck pulling, kipping, kicking, shrugging throughout the rep, craning the chin, or cutting off the controlled bottom position.",rom:"Start from a comfortable full hang with straight elbows and controlled shoulders; finish with chin clearly above the bar. Do not force a painful passive hang or exaggerated chest-to-bar finish."},
 'Seated cable row':{type:'row',attachment:'Close-grip neutral V-handle (two-hand parallel grip). A medium neutral MAG-style handle is also suitable; avoid an excessively wide bar for this row.',setup:'Sit tall with knees softly bent, feet braced and neutral spine. Start with arms extended and shoulders allowed to reach.',steps:'Pull handle toward lower ribs/upper abdomen, elbows travel back. Pause, then reach forward slowly without collapsing lumbar posture.',cues:['Move shoulder blades naturally.','Keep torso mostly still; no rocking for momentum.','Keep wrists straight.'],avoid:'Excessive backward lean or rounding lower back to gain reach.',rom:'Reach forward from shoulders while spine stays neutral.'},
 'Machine shoulder press':{type:'press',setup:"Use the selectorized overhead press machine. Adjust the seat so handles begin around shoulder level or slightly below, with forearms close to vertical and wrists stacked over elbows. Keep back and head supported, feet planted, and use a comfortable neutral or pronated grip according to the machine.",steps:"Press upward along the machine’s natural arc until arms are nearly straight without aggressively shrugging or losing back support. Lower under control until handles return to the deepest comfortable start position while shoulders remain supported and pain-free.",cues:["Seat height sets the bottom position: handles around shoulder level, not down at the upper chest.","Keep forearms aligned under the handles and wrists neutral.","Keep ribs stacked and back against the pad; do not arch to finish.","Allow natural scapular upward rotation as arms rise; do not forcibly pin shoulder blades down."],avoid:"Starting too deep, letting wrists fold back, flaring ribs, lifting off the pad, or forcing a fixed range that pinches the shoulder.",rom:"Lower to around shoulder height or the deepest comfortable position the machine allows; press to near-full elbow extension without forcing a hard lockout."},
 'Reverse pec deck':{type:'fly',setup:'Face the pad; adjust seat so handles are around shoulder height. Keep chest supported and elbows softly bent.',steps:'Sweep arms out/back in a wide arc. Pause briefly, then return slowly until rear delts are stretched without shoulder rolling forward excessively.',cues:['Think upper arms moving, not hands yanking.','Keep neck relaxed.','Use light enough load to avoid momentum.'],avoid:'Shrugging, swinging, or forcing hands far behind torso.',rom:'Controlled reach forward and open to a comfortable rear-delt contraction.'},
 'Rope triceps pushdown':{type:'triceps',attachment:'Rope attachment on the high pulley. Separate the rope ends slightly at lockout; a short straight bar is a reasonable alternative if the rope is unavailable.',setup:'Set cable high with rope. Stand tall, elbows near sides, wrists neutral.',steps:'Extend elbows until arms are straight without snapping lockout; separate rope ends slightly. Return slowly while upper arms stay mostly still.',cues:['Keep shoulders relaxed.','Move at the elbow; avoid leaning bodyweight onto rope.','Control the return.'],avoid:'Elbows drifting forward/back on every rep or torso swinging.',rom:'Bend elbows enough to feel triceps lengthen without shoulder discomfort.'},
 'Countermovement jump':{type:'jump',setup:'Stand balanced, feet around hip-to-shoulder width. Use an arm swing if it is part of your standard test.',steps:'Dip quickly to a comfortable countermovement, reverse direction explosively, jump tall, then land quietly with knees tracking over toes.',cues:['Max intent; stop sets when jump height or landing quality drops.','Land softly and regain balance.','Rest enough between reps for near-max output.'],avoid:'Chasing fatigue, stiff noisy landings, or knees collapsing inward.',rom:'Use a natural dip depth that lets you reverse explosively.'},
 'Approach jump':{type:'jump',setup:'Use a repeatable 2–3 step approach and take-off pattern. Clear the landing area.',steps:'Build controlled speed, plant decisively, swing arms, drive upward, then land balanced with hips/knees flexing.',cues:['Practice the same approach each rep.','Prioritize maximal jump quality, not conditioning.','Full recovery between efforts.'],avoid:'Slipping, uncontrolled take-off, or repeated jumps when fatigued.',rom:'Use your natural plant and dip; no forced positions.'},
 'Box jump':{type:'jump',setup:'Choose a stable, non-slip box height you can clear easily without an exaggerated knee tuck. Stand about one foot-length from the box, feet hip-width, and make sure the landing surface and space behind you are clear.',steps:'Load hips and arms with a small countermovement, then jump vertically and slightly forward onto the box. Land with both feet fully on the box, knees tracking over toes and hips flexed to absorb impact. Stand tall to finish, then step down one foot at a time; do not jump down.',cues:['Every rep is a crisp, maximal-intent jump—not a conditioning set.','Use the same take-off stance and landing standard each rep.','Choose a height that allows a quiet, balanced landing without pulling knees dramatically toward the chest.','Rest 90–150 seconds between sets; stop if jump quality or landing control drops.'],avoid:'Chasing box height by tucking knees, landing on the toes/edge, collapsing knees inward, or rebounding straight into the next rep.',rom:'Land fully on the box with hips and knees flexed; step down under control. Box height is a skill target, not a direct measurement of vertical jump height.'},
 'Pogo jumps':{type:'jump',setup:'Stand tall with feet under hips, knees soft, trunk braced.',steps:'Bounce from ankles with short ground contacts. Keep amplitude modest and rhythm springy.',cues:['Think stiff-but-not-locked ankles.','Keep contacts quiet and quick.','Stop if Achilles, shin or foot pain appears.'],avoid:'Deep squatting each rep or letting knees cave in.',rom:'Small elastic ankle motion; this is not a maximal-height jump.'},
 'Smith-machine squat':{type:'squat',setup:'Set bar across upper traps (not neck), feet positioned to allow a comfortable squat on the fixed track. Set safeties and test unloaded.',steps:'Brace, sit down between hips while knees track over toes. Descend as far as you can maintain foot pressure and neutral trunk, then drive up.',cues:['Keep whole foot planted: heel, big toe, little toe.','Knees track in line with toes.','Brace before each rep; avoid relaxing at the bottom.'],avoid:'Heels lifting, knees collapsing, bouncing, or forcing depth that causes pelvic/lumbar loss of control.',rom:'Use the deepest stable, pain-free depth your mobility permits.'},
 'Dumbbell Romanian deadlift':{type:'hinge',setup:'Hold dumbbells close to thighs, feet hip-width, knees softly bent. Brace trunk and set shoulders.',steps:'Push hips back while DBs slide close down legs. Stop when hamstrings are strongly tensioned and spine remains neutral; drive hips forward to stand.',cues:['Hinge at hips; knees bend only slightly.','Keep weights close to legs.','Finish tall without leaning back.'],avoid:'Squatting the movement, rounding lower back, or chasing floor depth.',rom:'End range is set by hamstring tension and neutral spine—not how low DBs reach.'},
 'Bulgarian split squat':{type:'squat',setup:'Set rear foot on a stable bench/step; front foot far enough forward to keep heel planted. Use support lightly for balance if needed.',steps:'Lower under control, letting front knee travel naturally over toes while hips descend. Drive through whole front foot to rise.',cues:['Keep pelvis square and torso position consistent.','Use a stance that feels stable.','Start bodyweight until balance and depth are reliable.'],avoid:'Narrow tightrope stance, pushing off rear leg, or letting front heel lift.',rom:'Use a deep comfortable range while front foot remains planted.'},
 'Standing calf raise':{type:'calf',setup:'Set shoulders under pads, balls of feet on platform, heels free. Use safety handles and stable foot placement.',steps:'Lower heels under control into a comfortable stretch, pause briefly, then rise onto toes and squeeze without bouncing.',cues:['Use full controlled ankle range.','Keep knees softly straight (not hyperlocked).','Pause in stretched and shortened positions.'],avoid:'Bouncing, partial fast reps, or rolling ankles outward.',rom:'Deep stretch only while ankle/Achilles remain comfortable.'},
 'Hanging knee raise':{type:'abs',setup:'Hang from secure bar with shoulders active; begin with knees slightly bent. Use a captain-chair machine if grip limits core work.',steps:'Curl pelvis upward and bring knees toward torso; lower slowly until hips return without swinging.',cues:['Think curl pelvis, not simply lift thighs.','Exhale as you curl up.','Control swing between reps.'],avoid:'Kipping, swinging legs, or arching lower back to create momentum.',rom:'Use the largest range you can control without swinging.'},
 'Kneeling cable crunch':{type:'abs',attachment:'Rope attachment on the high pulley. Hold the rope ends beside your temples; do not pull it down with your arms.',setup:'Kneel facing high cable with rope by temples. Keep hips stacked over knees and hold rope lightly.',steps:'Flex spine by bringing ribcage toward pelvis; hips remain mostly fixed. Return slowly until abs lengthen.',cues:['Think sternum toward pelvis.','Do not turn it into a hip hinge.','Exhale during the crunch.'],avoid:'Pulling with arms or sitting hips back to move the stack.',rom:'Use controlled spinal flexion; no yanking into end range.'},
 'Lat pulldown':{type:'pull',attachment:'Use the long lat-pulldown bar with a medium pronated (overhand) grip, about shoulder-width to 1.3× shoulder-width. Start with the straight section rather than an extreme-wide grip; use angled ends only if they feel better on your wrists. A neutral-grip attachment is a sound alternative if it gives you a more comfortable shoulder path.',setup:'Secure thighs under pads, sit tall and lean back only slightly. Brace your torso and begin with arms long overhead.',steps:'Allow the shoulder blades to rotate upward as you reach. Pull the elbows down toward your sides and bring the bar to the upper chest without turning the movement into a row. Return overhead slowly.',cues:['Think elbows down, hands as hooks.','Keep the torso angle nearly fixed; no rocking to move the load.','Use a controlled overhead stretch and full elbow extension.','Choose a grip that lets shoulders move comfortably; extreme width is unnecessary.'],avoid:'Pulling behind the neck, leaning far back, using momentum, or cutting off the overhead stretch.',rom:'Reach overhead as far as comfortable without painful pinching, then pull to upper chest with elbows down.'},
 'Pec deck fly':{type:'fly',setup:'Use the pec-deck machine with two hand-grip handles (not the version with forearm/elbow pads). Adjust the seat so your hands, elbows and shoulders sit roughly on the same horizontal plane when gripping the handles. Sit with your back against the backrest, feet planted, chest comfortably lifted, and elbows softly bent.',steps:'Start with the handles opened until you feel a clear but comfortable stretch across the chest. Sweep both handles forward in a wide arc, as if hugging a large tree, keeping the elbow bend nearly fixed. Bring the handles close together in front of mid-chest, pause and squeeze, then return slowly under control.',cues:['Grip the handles; your forearms do not rest on foam pads.','Keep a small, consistent bend in both elbows rather than turning the fly into a press.','Keep your back on the pad and shoulders relaxed; let the shoulder blades move naturally.','Set the machine start limiter so the handles do not pull your upper arms excessively behind your torso.','Use a light enough load to control the full arc without momentum.'],avoid:'Using a pad-supported pec-deck technique, straightening and rebending the elbows, shrugging, bouncing, or forcing an excessive shoulder stretch.',rom:'Open until you feel a strong chest stretch while the front of the shoulders remains comfortable; do not force the handles farther back.'},
 'Overhead cable triceps extension':{type:'triceps',attachment:'Default: rope on the high pulley, held with both hands. A pair of independent D-handles is an equally valid alternative if that lets your elbows and wrists find a more natural path; no attachment is inherently more hypertrophic.',setup:'Face away from the high pulley, step forward into a staggered stance and bring the rope behind your head. Keep ribs stacked, glutes lightly braced and upper arms elevated beside your head.',steps:'Bend your elbows so the rope travels behind your head, allowing a deep but comfortable triceps stretch. Extend your elbows to bring the hands forward/up without turning it into a shoulder press; return slowly.',cues:['Keep upper arms mostly fixed and elbows pointing generally forward.','Let the rope ends separate naturally as you extend; do not force them apart.','Use a load that preserves the overhead position and controlled stretch.','Keep lower back from arching to finish reps.'],avoid:'Flaring elbows excessively, shortening the stretched position, arching the back, or moving the shoulders to finish the rep.',rom:'Use the deepest comfortable elbow bend with stable shoulders, then extend to near-straight elbows.'},
 'Dumbbell shrugs':{type:'shrug',setup:'Stand tall with DBs at sides, arms long, neck neutral.',steps:'Elevate shoulders mostly straight upward, pause briefly, then lower slowly to a comfortable stretch.',cues:['Think shoulders toward ears, not rolling circles.','Keep head neutral.','Use straps if grip fails before traps.'],avoid:'Rolling shoulders, jerking, or neck jutting forward.',rom:'Full controlled elevation and depression.'},
 'Hammer curls':{type:'curl',setup:'Sit upright on a flat bench with back tall, feet planted and one dumbbell in each hand. Let both arms hang beside your thighs with palms facing inward.',steps:'Curl both dumbbells simultaneously, keeping palms facing each other and upper arms close to your sides. Squeeze without bringing elbows forward, then lower both weights together under control to near-full elbow extension.',cues:['Both arms move at the same time; do not alternate or cross-body curl.','Keep wrists straight and thumbs pointing upward.','Keep shoulders down and torso still.','Use a load that lets both sides move evenly without swinging.'],avoid:'Rocking backward, shrugging, rotating palms upward, or letting elbows drift forward.',rom:'Lower until elbows are comfortably near straight, then curl through the full controlled range.'},
 'Cable crunch (optional)':{type:'abs',setup:'Same kneeling setup as cable crunch; choose a load you can control.',steps:'Curl ribcage toward pelvis, pause, and return slowly.',cues:['Keep hips mostly fixed.','Exhale through the crunch.','Progress reps/load gradually.'],avoid:'Pulling with arms or using momentum.',rom:'Controlled spinal flexion without pain.'},
 'Farmer carry':{type:'carry',setup:'Pick up two challenging but manageable DBs with a hip hinge. Stand tall with ribs stacked and shoulders level.',steps:'Walk with short controlled steps, quiet feet and steady breathing. Set weights down with a hinge; do not drop.',cues:['Grip hard but do not shrug excessively.','Keep trunk upright and avoid leaning side-to-side.','Stop before posture or grip collapses.'],avoid:'Overloading until gait changes, leaning, or holding breath for the entire carry.',rom:'Walk a measured distance/time with consistent posture.'}
};
