 if(yt){var clip=yt.start!=null?'?start='+yt.start+'&end='+yt.end:'';return '<div class="exercise-demo"><div class="demo-heading">'+esc(yt.title)+'</div><div class="demo-video-frame"><iframe src="https://www.youtube-nocookie.com/embed/'+yt.id+clip+'" title="'+esc(yt.title)+'" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><p class="small">Exercise-specific filmed demonstration. Follow the written setup and ROM cues for your programmed variation.</p></div>';}
