 document.querySelectorAll('#exercises .exercise').forEach(function(card,i){
  var name=card.querySelector('b').textContent,ex=days[day].items[i],n=ex[1],last=state.logs.filter(function(l){return sameExerciseLog(l,name)}).slice(-1)[0];
  var rows='<div class="worksets"><b>Working sets · logged individually</b>';
  for(var s=1;s<=n;s++){var prev=state.logs.filter(function(l){return sameExerciseLog(l,name)}).slice(-n)[s-1];rows+='<div class="setrow-v2"><span>Set '+s+'</span><label>'+(name==='Box jump'?'Height (in)':'Load')+'<input type="number" step=".5" data-v2load="'+s+'" placeholder="'+(prev?esc(prev.load):(name==='Box jump'?'Box height':'Load'))+'"></label><label>Reps<input type="number" min="1" data-v2reps="'+s+'" placeholder="Reps"></label><label>'+(name==='Box jump'?'Quality (0–10)':'RIR')+'<input type="number" min="0" max="10" data-v2rir="'+s+'" placeholder="'+(name==='Box jump'?'10':'RIR')+'"></label><button class="v2save" data-v2set="'+s+'">Save set</button></div>'}
  rows+='</div>';card.insertAdjacentHTML('beforeend',rows);
  card.querySelectorAll('.v2save').forEach(function(btn){btn.onclick=function(){
   var s=+btn.dataset.v2set,load=card.querySelector('[data-v2load="'+s+'"]').value,reps=+card.querySelector('[data-v2reps="'+s+'"]').value,rir=card.querySelector('[data-v2rir="'+s+'"]').value;
   if(load===''||!reps||rir===''||+rir<0||+rir>10){alert(name==='Box jump'?'Enter box height, reps and a quality score from 0–10.':'Enter load, reps and RIR for this working set.');return}
   var old=state.logs.findIndex(function(l){return l.date===today()&&l.day===day&&sameExerciseLog(l,name)&&l.set===s&&!l.warmup});
   var item={date:today(),day:day,name:name,set:s,load:+load,reps:reps,rir:+rir,unit:ex[4],warmup:false};
   if(old>=0)state.logs[old]=item;else state.logs.push(item);save();btn.textContent='Saved';drawProgress();updateVolume();
  }});
  var rest=(name.indexOf('jump')>=0||name.indexOf('Jump')>=0)?120:((name.indexOf('press')>=0||name.indexOf('squat')>=0||name.indexOf('row')>=0||name.indexOf('Pull')>=0)?150:75);
  card.insertAdjacentHTML('beforeend','<button class="rest-v2" data-rest="'+rest+'">Start '+rest+'s rest timer</button>');
 });
